// @ts-nocheck -- type-checked in the motion-film project, not here.
// Generated by scripts/sync-film.mjs from motion-film/src/stage/SceneLighting.tsx. Edit it there, then run `npm run sync:film`.
import React from "react";
import { AbsoluteFill } from "remotion";

export type LightSpot = {
  /** Centre as % of frame. */
  x: number;
  y: number;
  /** Radius as % of frame width. */
  r: number;
  color: string;
  intensity: number;
};

/**
 * Scene-level light, applied once over the finished composition:
 *   warm key light, highlight spots, colour wash, vignette.
 * Plain alpha overlays only: Chrome applies blend modes inconsistently over separately
 * composited layers (3D flaps, CSS filters), which shows up as bands. Radial gradients use
 * many eased stops so they never crease.
 */
export const SceneLighting: React.FC<{
  warmth?: number;
  keyX?: number;
  keyY?: number;
  spots?: LightSpot[];
  vignette?: number;
  wash?: string;
  washOpacity?: number;
}> = ({ warmth = 0.35, keyX = 50, keyY = 22, spots = [], vignette = 0.4, wash, washOpacity = 0.12 }) => (
  <AbsoluteFill style={{ pointerEvents: "none" }}>
    {warmth > 0 ? (
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 95% 70% at ${keyX}% ${keyY}%, ${smooth("255,206,140", warmth * 0.32)})`,
        }}
      />
    ) : null}
    {spots.map((s, i) => (
      <AbsoluteFill
        key={i}
        style={{
          background: `radial-gradient(circle ${s.r * 10.8}px at ${s.x}% ${s.y}%, ${smooth(rgb(s.color), s.intensity * 0.7)})`,
        }}
      />
    ))}
    {wash ? <AbsoluteFill style={{ backgroundColor: wash, opacity: washOpacity }} /> : null}
    {vignette > 0 ? (
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 85% 70% at 50% 45%, ${smoothOut("40,18,10", vignette)})`,
        }}
      />
    ) : null}
  </AbsoluteFill>
);

/** Eased falloff stops (smoothstep-like) so gradients never band or crease. */
const smooth = (c: string, a: number) =>
  [0, 0.15, 0.3, 0.45, 0.6, 0.75, 0.9, 1]
    .map((t) => `rgba(${c},${(a * (1 - t * t * (3 - 2 * t))).toFixed(3)}) ${Math.round(t * 100)}%`)
    .join(", ");

const smoothOut = (c: string, a: number) =>
  [0, 0.5, 0.62, 0.74, 0.86, 1]
    .map((t) => {
      const u = Math.max(0, (t - 0.5) / 0.5);
      return `rgba(${c},${(a * u * u * (3 - 2 * u)).toFixed(3)}) ${Math.round(t * 100)}%`;
    })
    .join(", ");

const rgb = (hex: string) => {
  const n = parseInt(hex.replace("#", ""), 16);
  return `${(n >> 16) & 255},${(n >> 8) & 255},${n & 255}`;
};
